# -*- coding: utf-8 -*-
"""Lecture 49 vignette pool A -- Hematologic Malignancies Part I: overview, performance status, work-up and
transplant terms (s5-16), acute lymphoblastic leukemia (s18-29). Every slide in the range viewed at 1920 px
(s10 performance status table read from the picture).

KEYS ARE WRITTEN SHORT ON PURPOSE -- detail lives in the explanation.
EXPLANATIONS follow tools/question_writing/EXPLAIN_DEEP.md: the key names the decisive clue and the slide fact;
each wrong choice says why it fails for THIS patient, the replacing fact, and a "Tell:".

Laboratory ranges in the stems are standard adult or pediatric reference ranges and only set the scene; no key
turns on a range the deck does not give. Performance status stems describe the patient's day so that one grade row
of s10 fits, never a description halfway between two rows.

Deliberately NOT keyed: adult acute lymphoblastic leukemia survival as a precise figure (s18 "~30-40%" vs s28
"~40%"); any age 5-15 split (s18 vs s21); "most common leukemia" for any leukemia; Down syndrome as an acute
lymphoblastic leukemia risk factor (s21 and s34 give it for both acute leukemias, so it cannot separate them).
"""
import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from _cmse3_q import Q
from cms_e8l49_scope import *


def S(topic, io, q, opts, cite, slot):
    d = Q(topic, io, q, opts, cite); d["slot"] = slot; return d


def V(topic, io, q, opts, cite, slot, lead):
    d = S(topic, io, q, opts, cite, slot); d["lead"] = lead; return d


def ORD(d, asc):
    d["ordered"] = True; d["asc"] = asc; return d


